"""Rebuild inline vehicle symbols after editing static/images/vehicles/*.svg."""
from pathlib import Path
import re


root = Path(__file__).resolve().parents[1]
parts = [
    '{# Generated by scripts/build_vehicle_symbols.py; edit the source SVG assets. #}',
    '<svg xmlns="http://www.w3.org/2000/svg" width="0" height="0" '
    'aria-hidden="true" focusable="false" style="position:absolute;overflow:hidden"><defs>',
]
for asset in sorted((root / 'static/images/vehicles').glob('*.svg')):
    inner = re.sub(r'^<svg[^>]*>', '', asset.read_text(encoding='utf-8').strip())
    inner = re.sub(r'</svg>$', '', inner)
    parts.append(inner.replace('id="body"', f'id="vehicle-body-{asset.stem}"', 1))
parts.append('</defs></svg>')
(root / 'templates/vehicles/_body_symbols.html').write_text(
    '\n'.join(parts) + '\n', encoding='utf-8',
)
